ROOT = Path(__file__).resolve().parent
TRADE_THRESHOLD = 1e-8  # Fraction of the pre-trade value, for counting only.


@dataclass(frozen=True)
class Specification:
    tail_probability: float
    cost_bps: float
    slippage_bps: float
    resampled_probability: float

    def __post_init__(self):
        if not 0 < self.tail_probability < 0.5:
            raise ValueError("Tail probability must be between zero and one half")
        if not 0 <= self.resampled_probability <= 1:
            raise ValueError("Resampling probability must be between zero and one")
        if not 0 <= self.cost_bps or not 0 <= self.slippage_bps or not self.friction < 1:
            raise ValueError("Costs and slippage must be nonnegative and sum to less than 100%")

    @property
    def friction(self):
        return (self.cost_bps + self.slippage_bps) / 10_000


@dataclass(frozen=True)
class MarketData:
    opens: pd.DataFrame
    closes: pd.DataFrame
    distributions: pd.DataFrame
    risk_free: pd.Series

    def through(self, end):
        return MarketData(self.opens.loc[:end], self.closes.loc[:end],
                          self.distributions.loc[:end], self.risk_free.loc[:end])


def load_config():
    with (ROOT / "config.yaml").open(encoding="utf-8") as stream:
        config = yaml.safe_load(stream)
    for field in ("price_start", "backtest_start", "is_end", "backtest_end"):
        config[field] = pd.Timestamp(config[field])
    if not config["price_start"] < config["backtest_start"] < config["is_end"] < config["backtest_end"]:
        raise ValueError("Expected warm-up, IS start, IS end and OOS end in chronological order")
    for field in ("sessions_per_year", "signal_lag_sessions", "risk_free_lag_sessions",
                  "rebalance_sessions", "lookback_sessions", "bootstrap_rows",
                  "bootstrap_block_sessions", "solver_max_iterations"):
        if not isinstance(config[field], int) or config[field] < 1:
            raise ValueError(f"{field} must be a positive integer")
    if not config["denominator_floor"] > 0 or not config["solver_tolerance"] > 0:
        raise ValueError("The denominator floor and solver tolerance must be positive")
    if "SPY" not in config["universe"] or len(set(config["universe"])) != len(config["universe"]):
        raise ValueError("SPY must be in the universe once and all tickers must be distinct")
    return config


def prepare_market_data(prices, config):
    if not isinstance(prices.index, pd.DatetimeIndex) or prices.index.has_duplicates:
        raise ValueError("Expected a unique daily price index")
    prices = prices.set_axis(prices.index.as_unit("ns")).sort_index()
    universe = config["universe"]
    dates = prices["Close"]["SPY"].dropna().index
    if len(dates) == 0 or dates[0] < config["price_start"] or dates[-1] > config["backtest_end"]:
        raise ValueError("SPY calendar is empty or outside the requested dates")
    if dates[0] > config["price_start"] + pd.Timedelta(days=4) or dates[-1] < config["backtest_end"] - pd.Timedelta(days=4):
        raise ValueError("SPY calendar does not cover the requested dates")
    opens = prices["Open"].reindex(index=dates, columns=universe)
    closes = prices["Close"].reindex(index=dates, columns=universe)
    for label, frame in (("opening", opens), ("closing", closes)):
        invalid = ~np.isfinite(frame) | (frame <= 0)
        if invalid.any().any():
            symbols = list(invalid.columns[invalid.any()])
            raise ValueError(f"Missing or invalid {label} prices on SPY calendar: {symbols}")

    dividends = prices["Dividends"].reindex(index=dates, columns=universe, fill_value=0).fillna(0)
    distributions = dividends
    if "Capital Gains" in prices:
        gains = prices["Capital Gains"].reindex(index=dates, columns=universe, fill_value=0).fillna(0)
        distributions = dividends + gains
    if not np.isfinite(distributions).all().all():
        raise ValueError("Non-finite ETF distributions")
    if ((closes.shift(1) - distributions).iloc[1:] <= 0).any().any():
        raise ValueError("Distribution would exhaust the previous price")

    # Skip missing quotes and use only observations at or before the lagged date.
    quotes = prices["Close"][config["risk_free_ticker"]].dropna()
    quotes = quotes.reindex(dates, method="ffill").shift(config["risk_free_lag_sessions"])
    bill_price = 1 - (quotes / 100) * (91 / 360)
    risk_free = np.expm1(-np.log(bill_price) * (365 / (91 * config["sessions_per_year"])))
    return MarketData(opens, closes, distributions, risk_free)


def load_market_data(config):
    tickers = [*config["universe"], config["risk_free_ticker"]]
    start = config["price_start"].date().isoformat()
    end = (config["backtest_end"] + pd.Timedelta(days=1)).date().isoformat()
    key = hashlib.sha256("|".join(["yfinance-v1", start, end, *tickers]).encode()).hexdigest()[:16]
    name = f"{key}.csv.gz"
    snapshot = config["data"]["snapshots"][name]
    raw = gzip.decompress(snapshot["gzip"])
    snapshot_sha256 = hashlib.sha256(raw).hexdigest()
    if snapshot_sha256 != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch for market data snapshot {name}")

    raw = gzip.decompress(raw)
    with BytesIO(raw) as file:
        fetched_at = file.readline().decode("utf-8").strip()
        datetime.fromisoformat(fetched_at)
        input_sha256 = hashlib.sha256(file.getbuffer()[file.tell():]).hexdigest()
        prices = pd.read_csv(file, header=[0, 1], index_col=0, parse_dates=True)
    market = prepare_market_data(prices, config)

    print("Data source: yfinance daily ETF prices, corporate actions and ^IRX quotes "
          "from Yahoo Finance (query2.finance.yahoo.com, auto_adjust=False) embedded in config "
          f"under data.snapshots (decompressed sha256 {snapshot_sha256} for {name}); "
          "the script does not call yfinance, FRED or any host and reads no data_cache", flush=True)
    print(f"Input SHA-256: {input_sha256}", flush=True)
    print(f"DATA_SHA256: {snapshot_sha256}", flush=True)
    print("MARKET_DATA_SNAPSHOT: " + json.dumps({
        "path": "config.yaml", "key": "data.snapshots", "file": name, "sha256": snapshot_sha256,
    }), flush=True)
    return market, fetched_at


def scenario_probabilities(n_rows, probability, config, signal_date):
    if probability == 0:
        return np.full(n_rows, 1 / n_rows)
    rng = np.random.default_rng([config["bootstrap_seed"], signal_date.toordinal()])
    draws = config["bootstrap_rows"]
    block_length = config["bootstrap_block_sessions"]
    starts = rng.integers(n_rows, size=math.ceil(draws / block_length))
    indices = ((starts[:, None] + np.arange(block_length)) % n_rows).ravel()[:draws]
    # Repeated draws can be represented by the combined mass on their original rows.
    return (1 - probability) / n_rows + probability * np.bincount(indices, minlength=n_rows) / draws


def tail_coefficients(ordered, masses, probability):
    cutoff = ordered[np.searchsorted(np.cumsum(masses), probability)]
    inside = ordered < cutoff
    same = ordered == cutoff
    remaining = np.clip(probability - masses[inside].sum(), 0.0, masses[same].sum())
    return (masses * inside + masses * same * (remaining / masses[same].sum())) / probability


def optimize_target(scenarios, masses, risk_free, previous_target, config, spec, signal_date):
    positive_mass = masses > 0
    scenarios = scenarios[positive_mass]
    masses = masses[positive_mass]
    excess = scenarios - risk_free
    n_assets = excess.shape[1]
    equal = np.full(n_assets, 1 / n_assets)
    corners = np.eye(n_assets)
    rng = np.random.default_rng([config["solver_seed"], signal_date.toordinal()])
    starts = np.vstack([previous_target, equal, corners,
                        rng.dirichlet(np.ones(n_assets), size=config["random_starts"])])
    floor = config["denominator_floor"]

    def objective(weights):
        values = np.einsum("ij,j->i", excess, weights)
        order = np.argsort(values)
        ordered = values[order]
        ordered_mass = masses[order]
        lower_coeff = tail_coefficients(ordered, ordered_mass, spec.tail_probability)
        upper_coeff = tail_coefficients(-ordered[::-1], ordered_mass[::-1], spec.tail_probability)[::-1]
        supports = excess[order]
        lower_gradient = np.einsum("i,ij->j", lower_coeff, supports)
        upper_gradient = np.einsum("i,ij->j", upper_coeff, supports)
        lower = lower_gradient @ weights
        upper = upper_gradient @ weights
        denominator = max(abs(lower), floor)
        gradient = upper_gradient / denominator
        if abs(lower) > floor:
            gradient = gradient - (upper / denominator**2) * np.sign(lower) * lower_gradient
        return -upper / denominator, -gradient

    unit_sum = {"type": "eq", "fun": lambda w: w.sum() - 1, "jac": lambda w: np.ones_like(w)}
    best = previous_target
    best_loss = objective(best)[0]
    for start in np.unique(starts, axis=0):
        start_loss = objective(start)[0]
        if start_loss < best_loss:
            best, best_loss = start, start_loss
        result = minimize(objective, start, jac=True, bounds=[(0, 1)] * n_assets,
                          constraints=unit_sum, method="SLSQP",
                          options={"maxiter": config["solver_max_iterations"],
                                   "ftol": config["solver_tolerance"]})
        proposal = result.x
        if (np.isfinite(proposal).all() and abs(proposal.sum() - 1) <= 1e-7
                and proposal.min() >= -1e-7 and proposal.max() <= 1 + 1e-7):
            weights = np.maximum(proposal, 0)
            weights /= weights.sum()
            loss = objective(weights)[0]
            if loss < best_loss:
                best, best_loss = weights, loss
    return best


def execute_at_open(positions, cash, opening, target, friction):
    opening_values = positions * opening
    before = math.fsum((*opening_values, cash))

    # The after-cost value solves V + rate * sum(abs(V * w - open values)) = before.
    # Keep the lower bisection bound feasible, so purchases are funded after all fees.
    low, high = 0.0, before
    for _ in range(55):
        middle = (low + high) / 2
        proposed = middle * target / opening
        new_values = proposed * opening
        traded = np.abs(new_values - opening_values).sum()
        remaining = math.fsum((before, *(-new_values), -friction * traded))
        if remaining >= 0:
            low = middle
        else:
            high = middle

    new_positions = low * target / opening
    new_values = new_positions * opening
    traded_by_asset = np.abs(new_values - opening_values)
    cash = math.fsum((before, *(-new_values), -friction * traded_by_asset.sum()))
    if not math.isfinite(cash) or cash < 0:
        raise ArithmeticError("Opening rebalance would require borrowing")
    turnover = traded_by_asset.sum() / (2 * before)
    trades = np.count_nonzero(traded_by_asset > TRADE_THRESHOLD * before)
    return new_positions, cash, turnover, trades


def simulate(market, config, spec, equal_weight=False):
    dates = market.closes.index
    first = dates.searchsorted(config["backtest_start"])
    lookback = config["lookback_sessions"]
    lag = config["signal_lag_sessions"]
    if first - lag < lookback or first >= len(dates):
        raise ValueError("Insufficient warm-up or evaluation prices for the requested start")
    if not np.isfinite(market.risk_free.iloc[first - lag:]).all():
        raise ValueError("Missing or invalid lagged risk-free quotes in evaluation")

    previous_close = market.closes.shift(1)
    ex_distribution_close = previous_close - market.distributions
    factors = (previous_close / ex_distribution_close).to_numpy()
    close_returns = (market.closes / ex_distribution_close - 1).to_numpy()
    opens = market.opens.to_numpy()
    closes = market.closes.to_numpy()
    rates = market.risk_free.to_numpy()
    n_assets = closes.shape[1]
    target = np.full(n_assets, 1 / n_assets)
    positions = np.zeros(n_assets)
    cash = previous_value = 1.0
    results = []

    for day in range(first, len(dates)):
        turnover, trades = 0.0, 0
        if (day - first) % config["rebalance_sessions"] == 0:
            if not equal_weight:
                information = day - lag
                history = close_returns[information + 1 - lookback:information + 1]
                signal_date = dates[information]
                masses = scenario_probabilities(len(history), spec.resampled_probability,
                                                 config, signal_date)
                target = optimize_target(history, masses, rates[information], target,
                                         config, spec, signal_date)
            positions, cash, turnover, trades = execute_at_open(
                positions * factors[day], cash, opens[day], target, spec.friction
            )
        else:
            positions = positions * factors[day]

        closing_value = positions @ closes[day] + cash
        results.append((closing_value / previous_value - 1, rates[day], turnover,
                        trades, cash / closing_value))
        previous_value = closing_value

    return pd.DataFrame(results, index=dates[first:],
                        columns=["daily_return", "risk_free", "turnover", "trades", "cash_fraction"])


def metrics(daily_results, sessions_per_year):
    if len(daily_results) < 2:
        raise ValueError("A reporting period needs at least two return observations")
    returns = daily_results["daily_return"].to_numpy()
    excess = returns - daily_results["risk_free"].to_numpy()
    wealth = np.r_[1, np.cumprod(1 + returns)]
    annualizer = np.sqrt(sessions_per_year)
    volatility = returns.std(ddof=1)
    excess_volatility = excess.std(ddof=1)
    return {
        "cagr": float(wealth[-1] ** (sessions_per_year / len(returns)) - 1),
        "ann_vol": float(annualizer * volatility),
        "sharpe": float(annualizer * returns.mean() / volatility) if volatility else None,
        "sharpe_excess": float(annualizer * excess.mean() / excess_volatility) if excess_volatility else None,
        "max_drawdown": float(np.min(wealth / np.maximum.accumulate(wealth) - 1)),
        "total_return": float(wealth[-1] - 1),
        "turnover": float(daily_results["turnover"].sum() * sessions_per_year / len(returns)),
        "n_trades": int(daily_results["trades"].sum()),
    }


def period_metrics(daily_results, config):
    in_sample = daily_results.index <= config["is_end"]
    annual_sessions = config["sessions_per_year"]
    return {"is": metrics(daily_results.loc[in_sample], annual_sessions),
            "oos": metrics(daily_results.loc[~in_sample], annual_sessions),
            "full": metrics(daily_results, annual_sessions)}


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.parse_args()
    config = load_config()
    official = Specification(**config["official"])
    alternatives = {label: replace(official, **changes)
                    for label, changes in config["robustness_is"].items()}
    if len(set(alternatives.values()) | {official}) != len(alternatives) + 1:
        raise ValueError("Robustness alternatives must each define a distinct specification")

    market, fetched_at = load_market_data(config)
    print(f"DATA_FETCHED_AT: {fetched_at}", flush=True)
    print("PRICE_ADJUSTMENT: yfinance split-adjusted OHLC; causal ex-date total-return reinvestment", flush=True)

    print("ROBUSTNESS (IS ONLY)", flush=True)
    is_market = market.through(config["is_end"])
    official_is = simulate(is_market, config, official)
    trials = 1
    for label, spec in {"official_is": official, **alternatives}.items():
        daily_results = official_is if label == "official_is" else simulate(is_market, config, spec)
        trials += label != "official_is"
        stats = metrics(daily_results, config["sessions_per_year"])
        print(f"  {label} {spec} | {json.dumps(stats, allow_nan=False)}", flush=True)

    daily_results = simulate(market, config, official)
    pd.testing.assert_frame_equal(daily_results.loc[:config["is_end"]], official_is)
    benchmark = simulate(market, config, official, equal_weight=True)
    stats = period_metrics(daily_results, config)
    baseline = period_metrics(benchmark, config)
    if stats["is"]["n_trades"] == 0 or stats["oos"]["n_trades"] == 0:
        raise RuntimeError("The official path must execute trades in both periods")

    print("LOOK_AHEAD_CHECK: lagged close signals; open sizing; lagged ^IRX; prior-close ex-date basis; IS prefix equal")
    print(f"MIN_CASH_FRACTION: strategy={daily_results['cash_fraction'].min():.12g}, "
          f"benchmark={benchmark['cash_fraction'].min():.12g}")
    for period in ("is", "oos", "full"):
        print(f"{period.upper()} strategy | {json.dumps(stats[period], allow_nan=False)}")
        print(f"{period.upper()} equal-weight benchmark | {json.dumps(baseline[period], allow_nan=False)}")
    result = {
        "strategy": config["strategy"],
        "data_range": {"start": daily_results.index[0].date().isoformat(),
                       "end": daily_results.index[-1].date().isoformat()},
        **stats,
        "benchmark": {"name": "equal_weight_rebalanced", **baseline},
    }
    print(f"PARAM_COMBOS_TRIED: {trials}")
    print("RESULTS_JSON: " + json.dumps(result, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(14 * 60)
    main()
